extends Node2D

func build():
	var scene = PackedScene.new()
	var root = Node2D.new()
	root.name = "Animator"

	var target = Node2D.new()
	target.name = "Target"
	root.add_child(target)
	target.owner = root

	var ctrl = Node.new()
	ctrl.name = "TweenController"
	root.add_child(ctrl)
	ctrl.owner = root

	var err = scene.pack(root)
	assert(err == OK, "pack failed: %s" % err)
	err = ResourceSaver.save(scene, "res://scenes/Animator.tscn")
	assert(err == OK, "save failed: %s" % err)
	print("saved res://scenes/Animator.tscn")
	root.free()

build()

